import pytest


def age_at(born: int, now: int) -> int:
    """Whole years from the birth year `born` to the given year `now`.

    The current year is passed in; this function never reads the clock.
    Raises ValueError when born > now.
    """
    if born > now:
        raise ValueError(f"birth year {born} is after current year {now}")
    return now - born


def test_age_at_whole_years() -> None:
    assert age_at(1990, 2024) == 34


def test_age_at_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_at_one_year_apart() -> None:
    assert age_at(1999, 2000) == 1


def test_age_at_born_after_now_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)
